with with_windows as (select id, dept_name, budget, lag(budget) over (partition by dept_name, location order by budget, id) as prev_budget, row_number() over (partition by dept_name, location order by budget, id) as seq_no from departments) select id, dept_name, budget, prev_budget, seq_no, case when dept_name rlike '^(HR|Finance)$' then 'EXTENDED' when dept_name rlike '^(Engineering|Sales)$' then 'PRIORITY' else 'CORE' end as dept_name_zone from with_windows order by prev_budget desc;
